import{t as e}from"./react-CP9HUTOw.js";var t=e(),n=[[`A / ←`,`Steer to port (hold)`],[`D / →`,`Steer to starboard (hold)`],[`Shift (held)`,`Hold the helm where it is (no self-centring)`],[`Space`,`Centre the helm`],[`W / ↑`,`Trim (pull in) the mainsheet`],[`S / ↓`,`Ease the mainsheet`],[`E / Q`,`Trim / ease the jib sheet`],[`M / J`,`Toggle auto-trim assist for main / jib`],[`K`,`Toggle auto crew weight`],[`X`,`Release both sheets (sails luff; head to wind as well to stop)`],[`Z / Shift+Z`,`Flatten the sails (depower) / power them up again, a quarter at a time`],[`P`,`Pause / resume`],[`R`,`Reset to the scenario start`],[`C`,`Cycle camera: chase (the wheel zooms), scenic, helm (drag to look around), orbit, drone, top`],[`U`,`Sound on or off (levels: More → Graphics and sound)`],[`B`,`Drone view: fly back to the boat`],[`F`,`Show physics force arrows`],[`G`,`Show the physics debug panel`],[`V`,`Validation dashboard (live charts, table, CSV export)`],[`L / N`,`Place labels / minimap`],[`Esc`,`Close the open panels and menus`],[`H or ?`,`This help`]];function r({onClose:e,onTutorial:r}){return(0,t.jsx)(`div`,{className:`overlay`,role:`dialog`,"aria-modal":`true`,"aria-label":`Help`,onClick:e,children:(0,t.jsxs)(`section`,{className:`panel help`,onClick:e=>e.stopPropagation(),children:[(0,t.jsxs)(`div`,{className:`row left help-top`,children:[(0,t.jsx)(`button`,{className:`primary`,onClick:r,autoFocus:!0,children:`Start the tutorial`}),(0,t.jsx)(`span`,{className:`fine`,children:`A step-by-step lesson: steer, trim, tack, gybe and stop (about 5 minutes).`})]}),(0,t.jsx)(`h3`,{children:`How to sail`}),(0,t.jsx)(`p`,{children:`You helm a National Squib. Sail angle is set by the sheet: the sail blows out until the sheet stops it. Too far out and it luffs (no drive); too far in and it stalls. Watch the status chips under the sails. To tack, steer through the wind keeping speed; to stop, release the sheets and head into the wind.`}),(0,t.jsx)(`table`,{children:(0,t.jsx)(`tbody`,{children:n.map(([e,n])=>(0,t.jsxs)(`tr`,{children:[(0,t.jsx)(`td`,{className:`key`,children:e}),(0,t.jsx)(`td`,{children:n})]},e))})}),(0,t.jsx)(`h3`,{children:`Your Squib`}),(0,t.jsx)(`p`,{children:`In Scenario → Boat, choose a Rondar (the modern standard: its cockpit drains itself), a classic Hunter or Parker hull (water that comes over the rail stays until your crew bails it, so keep the rail out of the water), or the new Hyde B3 / Batt sails. The burgee at the masthead shows the apparent wind. With wind against tide, as in the harbour entrance on the ebb, expect short, steep waves; More instruments shows the waves.`}),(0,t.jsx)(`h3`,{children:`Racing`}),(0,t.jsx)(`p`,{children:`In Scenario, choose a course and up to 20 AI boats. Watch the flags: class flag at the warning signal, P (or U, black) at the preparatory signal, coming down at one minute; the start when the class flag comes down. Flag X: someone was over early (return behind the line); First Substitute: general recall. Port tack keeps clear of starboard, windward of leeward, clear astern of clear ahead, and a boat tacking keeps clear. If you hit a boat you should have kept clear of, take a Two-Turns Penalty (two turns the same way, each with a tack and a gybe); for touching a mark, one turn. The judge is a simplified subset of the racing rules, not an authoritative one.`}),(0,t.jsx)(`p`,{className:`fine`,children:`On the River Dart: terrain, buildings, piers and the shoreline come from open data; water depths mid-channel, individual moorings, most ferry timetables, vessel sizes, roof shapes and the tidal stream are provisional estimates (see Layers). You can run aground: the keel stops you in shallow water, and moored boats, ferries and the boats leaving Dart Marina are solid. The boat heels dynamically, the boom swings on its own and can gybe unexpectedly by the lee, and the wind has seeded gusts and shifts (dark patches on the water are puffs). Boat dimensions are from class sources; hydrodynamic and sail coefficients are estimates awaiting calibration. Weather and tide sources are labelled in the instruments. Not for navigation or performance prediction.`}),(0,t.jsx)(`button`,{className:`primary`,onClick:e,children:`Close`})]})})}export{r as Help};
